         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="fullName">Full name *</label>
             <input id="fullName" name="fullName" type="text" placeholder="Taylor Morgan" autocomplete="name" required>
             <p class="validation-message" id="fullName-error" aria-live="polite"></p>
