             <label for="email">Email address *</label>
             <input id="email" name="email" type="email" placeholder="taylor@example.com" autocomplete="email" required>
             <p class="validation-message" id="email-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number</label>
             <input id="phone" name="phone" type="tel" placeholder="+1 555-123-4567" autocomplete="tel">
             <p class="helper-text" id="phone-helper">Optional. Use digits with spaces or hyphens, for example: +1 555-123-4567.</p>
             <p class="validation-message" id="phone-error" aria-live="polite"></p>
