   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");

     const fieldRules = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullName-error"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }
           if (value.trim().length < 2) {
             return "Enter your full name.";
           }
           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }
           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }
           const phonePattern = /^\+?[0-9\s\-()]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return "Enter a valid phone number using digits, spaces, hyphens, or parentheses.";
           }
           return "";
         }
       }
     };

     function setFieldState(fieldName) {
       const field = fieldRules[fieldName];
       const message = field.validate(field.input.value);
       const wrapper = field.input.closest(".form-field");

       field.error.textContent = message;
       field.input.setAttribute("aria-invalid", message ? "true" : "false");
       wrapper.classList.toggle("invalid", Boolean(message));

       return !message;
     }

     Object.keys(fieldRules).forEach((fieldName) => {
       const { input } = fieldRules[fieldName];

       input.addEventListener("blur", () => {
         setFieldState(fieldName);
       });

       input.addEventListener("input", () => {
         if (input.getAttribute("aria-invalid") === "true") {
           setFieldState(fieldName);
         }
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";

       const isValid = Object.keys(fieldRules)
         .map((fieldName) => setFieldState(fieldName))
         .every(Boolean);

       if (!isValid) {
         statusMessage.textContent = "Please correct the highlighted fields.";
         return;
       }

       statusMessage.textContent = "Your message is ready to send.";
     });
